(()=>{
 const meta=n=>document.querySelector(`meta[name="${n}"]`).content;const base=meta('site-base'),token=meta('editor-token'),user=JSON.parse(meta('current-user'));const $=id=>document.getElementById(id);
 async function api(route,body){const r=await fetch(base+'/fara-admin/api.php?r='+route,{method:body?'POST':'GET',headers:{'X-Editor-Token':token,...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(r.status===401){location.reload();throw Error('نشست تمام شده است.')}if(!r.ok)throw Error(d.error||'درخواست انجام نشد.');return d}
 $('account-name').textContent=user.username+(user.role==='admin'?' · مدیر':' · ویرایشگر');$('manage-users').hidden=user.role!=='admin';
 const dialog=$('account-dialog'),message=$('account-message');function open(mode){dialog.showModal();message.textContent='';$('users-panel').hidden=mode!=='users';$('change-panel').hidden=mode!=='password';$('account-title').textContent=mode==='users'?'مدیریت کاربران':'تغییر رمز عبور';if(mode==='users')loadUsers().catch(e=>message.textContent=e.message)}
 $('manage-users').onclick=()=>open('users');$('change-password').onclick=()=>open('password');$('close-account').onclick=()=>dialog.close();$('logout').onclick=async()=>{if(!confirm('از پنل خارج می‌شوی؟'))return;try{await api('logout',{});location.reload()}catch(e){alert(e.message)}};
 function el(tag,text){const e=document.createElement(tag);if(text)e.textContent=text;return e}
 async function loadUsers(){const {users}=await api('users');const root=$('user-list');root.replaceChildren();for(const u of users){const card=el('article');card.className='user-card';card.append(el('b',u.username),el('p',(u.role==='admin'?'مدیر':'ویرایشگر')+' · '+(u.active?'فعال':'غیرفعال')+(u.mustChange?' · نیازمند تغییر رمز':'')));const role=el('select');role.append(new Option('مدیر','admin'),new Option('ویرایشگر','editor'));role.value=u.role;role.setAttribute('aria-label','نقش '+u.username);const active=el('input');active.type='checkbox';active.checked=u.active;const label=el('label','حساب فعال');label.prepend(active);const apply=el('button','ذخیرهٔ نقش و وضعیت');apply.type='button';apply.className='button';apply.onclick=()=>mutate({action:'update',id:u.id,role:role.value,active:active.checked});const pass=el('input');pass.type='password';pass.autocomplete='new-password';pass.placeholder='رمز موقت جدید (حداقل ۱۲ نویسه)';pass.minLength=12;pass.maxLength=128;pass.setAttribute('aria-label','رمز موقت '+u.username);const reset=el('button','تعیین رمز موقت');reset.type='button';reset.className='button';reset.onclick=()=>mutate({action:'reset',id:u.id,password:pass.value});card.append(role,label,apply,pass,reset);root.append(card)}}
 async function mutate(data){message.textContent='';const password=$('admin-confirm').value;if(!password){message.textContent='برای مدیریت کاربران رمز فعلی خودت را وارد کن.';return}dialog.querySelectorAll('button').forEach(b=>b.disabled=true);try{await api('users',{...data,adminPassword:password});message.textContent='ذخیره شد.';$('new-user').reset();await loadUsers()}catch(e){message.textContent=e.message}finally{dialog.querySelectorAll('button').forEach(b=>b.disabled=false)}}
 $('new-user').onsubmit=e=>{e.preventDefault();mutate({action:'add',...Object.fromEntries(new FormData(e.target))})};$('change-form').onsubmit=async e=>{e.preventDefault();message.textContent='';try{await api('password',Object.fromEntries(new FormData(e.target)));e.target.reset();message.textContent='رمز عبور تغییر کرد.'}catch(e){message.textContent=e.message}};
})();
